// POST {"email":"someone@club.org"}
//
// DOES NOT THROW ON BAD INPUT. Throwing here errors the workflow, and with responseMode
// "responseNode" no response node is ever reached — so the caller gets HTTP 200 with an empty
// body and no way to tell what went wrong. Verified against the live webhook (Vhea,
// 2026-09-09). Invalid input is routed to a proper 400 instead.
//
// Lower-cased and trimmed so the mirror lookup, the HubSpot search and the response all speak
// about the same string: addresses arrive from replies, CSV pastes and typed input, and
// "Someone@Club.org " is the same person.
const body = ($json && $json.body) || $json || {};
const raw = String(body.email || '');
const email = raw.trim().toLowerCase();
const valid = !!email && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
return [{ json: { email, valid, given: raw } }];

parameters.responseBody:
={{ JSON.stringify({
  found: true,
  source: 'mirror',
  contact: {
    hs_object_id: Number($json.hs_object_id),   // bigint arrives quoted; keep one type across both paths
    email: $json.email,
    firstname: $json.firstname,
    lastname: $json.lastname,
    company: $json.company,
    state: $json.state,
    lifecyclestage: $json.lifecyclestage,
    hs_lastmodifieddate: $json.hs_lastmodifieddate,
    synced_at: $json.synced_at
  }
}) }}

parameters.jsonBody:
={{ JSON.stringify({
  filterGroups: [{ filters: [{ propertyName: 'email', operator: 'EQ', value: $json.email_in }] }],
  properties: ['email','firstname','lastname','company','state','lifecyclestage','hs_lastmodifieddate'],
  limit: 1
}) }}

parameters.jsCode:
// ALWAYS RETURNS ONE ITEM, found or not — same reason as the SQL above. An empty result would
// stop the chain and leave the caller waiting for a response that never comes.
//
// The address searched for is carried through as email_in so the "not found" answer can name it.
const email = $('Prepare the email to search').first().json.email;
const first = ($input.first().json.results || [])[0];

if (!first) {
  return [{ json: { found: false, email_in: email, rows: [] } }];
}

const p = first.properties || {};
const contact = {
  hs_object_id: Number(first.id),
  email: p.email || null,
  firstname: p.firstname || null,
  lastname: p.lastname || null,
  company: p.company || null,
  state: p.state || null,
  lifecyclestage: p.lifecyclestage || null,
  hs_lastmodifieddate: p.hs_lastmodifieddate || null,
  synced_at: new Date().toISOString(),
};

// CACHE WHAT WE JUST PAID FOR. A miss cost an API call; writing it back means the next lookup for
// this person is a local query. Same upsert shape as the sync, so the two can never disagree about
// the row format.
return [{ json: { found: true, email_in: email, contact, rows: [contact] } }];
